describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ]);

    it("returns 0 for empty lines", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 3 },
      ];
      expect(calc.computeShippingCents(lines, 1000)).toBe(0);
    });

    it("selects first bracket at boundary", () => {
      // 500g exactly → first bracket (300)
      const lines = [makeLine("a", 500, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects next bracket when weight exceeds boundary", () => {
      // 501g → second bracket (600)
      const lines = [makeLine("a", 501, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      // 5000g → third bracket (1200)
      const lines = [makeLine("a", 5000, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        [
          { upToGrams: 500, costCents: 300 },
          { upToGrams: 1000, costCents: 600 },
        ],
        2000,
      );
      const lines = [makeLine("a", 1500, 1)];
      expect(calcWithOverflow.computeShippingCents(lines, 1000)).toBe(2000);
    });

    it("defaults overflow to heaviest bracket cost", () => {
      // No overflowCostCents: uses last bracket
      const lines = [makeLine("a", 10000, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ]);
      const lines = [makeLine("a", 400, 1)];
      expect(unordered.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("multiplies weight by quantity", () => {
      // 3 items at 200g each = 600g → second bracket (600)
      const lines = [makeLine("a", 200, 3)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(600);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { CartConfig, CheckoutCollaborators } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { Product, CartLine } from "../src/product.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker, InventoryDecision } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const product = (id: string, price: number, weight?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  weightGrams: weight,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to empty cart", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity for same product", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      cart.add(product("a", 100), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 100), 0)).toThrow(RangeError);
      expect(() => cart.add(product("a", 100), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 100), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes existing product and returns true", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity for existing product", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 3);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("x", 5)).toThrow("Product x is not in the cart");
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      cart.add(product("b", 200), 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns deep copy of lines", () => {
      const cart = new Cart();
      const p = product("a", 100);
      cart.add(p, 2);
      const snap = cart.snapshot();
      expect(snap).toHaveLength(1);
      expect(snap[0].product.id).toBe("a");
      expect(snap[0].quantity).toBe(2);
      // Mutating snapshot should not affect cart
      (snap[0] as { quantity: number }).quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      cart.add(product("b", 300), 1);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(500);
    });

    it("applies discount policy, tax on discounted subtotal, then shipping", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const tax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
        region: "US-CA",
      });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();

      expect(discount.computeDiscountCents).toHaveBeenCalledWith(1000);
      expect(totals.discountCents).toBe(200);
      // Tax is computed on discounted subtotal: 1000 - 200 = 800
      expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
      expect(totals.taxCents).toBe(80);
      // Shipping is computed against discounted subtotal
      expect(shipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800,
      );
      expect(totals.shippingCents).toBe(500);
      // Total = discountedSubtotal + tax + shipping = 800 + 80 + 500
      expect(totals.totalCents).toBe(1380);
    });

    it("clamps discount to [0, subtotal]", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 9999,
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(product("a", 500), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500);
      expect(totals.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => -100,
      };
      const cart = new Cart({ discountPolicy: discount });
      cart.add(product("a", 500), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
      expect(totals.subtotalCents).toBe(500);
    });

    it("clamps negative tax to 0", () => {
      const tax: TaxCalculator = {
        computeTaxCents: () => -50,
      };
      const cart = new Cart({ taxCalculator: tax });
      cart.add(product("a", 500), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shipping: ShippingCalculator = {
        computeShippingCents: () => -100,
      };
      const cart = new Cart({ shippingCalculator: shipping });
      cart.add(product("a", 500), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("returns all zeros for empty cart", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(0);
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(0);
    });

    it("defaults to NoDiscount, NoTax, FreeShipping, US region", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(2000);
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(2000);
    });
  });

  describe("checkout", () => {
    it("refreshes prices via priceFetcher", async () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(150),
      };
      const result = await cart.checkout({ priceFetcher });
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(result.totals.subtotalCents).toBe(300); // 150 * 2
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(product("a", 100), 5);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        } satisfies InventoryDecision),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        InventoryError,
      );
      try {
        await cart.checkout({ inventoryChecker });
      } catch (e) {
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(2);
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(product("a", 100), 10);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        } satisfies InventoryDecision),
      };
      await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
        InventoryError,
      );
    });

    it("passes when inventory is sufficient", async () => {
      const cart = new Cart();
      cart.add(product("a", 100), 2);
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 10,
        } satisfies InventoryDecision),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(200);
    });

    it("uses asyncTaxProvider for tax calculation", async () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 100,
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 500,
      };
      const cart = new Cart({
        discountPolicy: discount,
        shippingCalculator: shipping,
      });
      cart.add(product("a", 1000), 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal=1000, discount=100, discounted=900, tax=10% of 900=90
      expect(result.totals.taxCents).toBe(90);
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(900 + 90 + 500);
    });

    it("propagates priceFetcher rejection", async () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("fetch failed");
    });

    it("propagates asyncTaxProvider rejection", async () => {
      const cart = new Cart();
      cart.add(product("a", 100), 1);
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("works with no collaborators (uses sync defaults)", async () => {
      const cart = new Cart();
      cart.add(product("a", 200), 3);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(600);
      expect(result.lines).toHaveLength(1);
    });

    it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
      const discount: DiscountPolicy = { computeDiscountCents: () => 50 };
      const shipping: ShippingCalculator = { computeShippingCents: () => 300 };
      const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
      cart.add(product("a", 100), 2);
      cart.add(product("b", 200), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockImplementation((id: string) =>
          id === "a" ? Promise.resolve(120) : Promise.resolve(250),
        ),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.08),
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // Refreshed: a=120*2=240, b=250*1=250, subtotal=490
      expect(result.totals.subtotalCents).toBe(490);
      // Discount clamped: min(max(0,50),490) = 50
      expect(result.totals.discountCents).toBe(50);
      // Tax: 8% of (490-50)=440 → 35.2 → 35
      expect(result.totals.taxCents).toBe(35);
      expect(result.totals.shippingCents).toBe(300);
      expect(result.totals.totalCents).toBe(440 + 35 + 300);
    });
  });
});

